        "title": "The Old Library Mystery",
        "storyContext": "Priya visits her grandmother's library and finds books marked VI, XII, VIII. She wonders why they don't use normal numbers.",
        "points": [
          {
            "label": "Setting",
            "text": "An old Delhi library with ancient books and dusty shelves"
          }
        ],
        "inSimpleWords": "Priya finds mysterious symbols on book spines.",
